mapper.select:
SELECT 1 FROM facts
  WHERE kb_id = #{kbId} AND subject_id = #{subjectId}
    AND layer = 'open' AND phrase = #{phrase}
    AND object_id IS NOT DISTINCT FROM #{objectId}
    AND object_value IS NOT DISTINCT FROM #{objectValue,typeHandler=tech.seexun.jknow.store.typehandler.JsonNodeTypeHandler}
    AND invalidated_at IS NULL
  LIMIT 1

SELECT 1 FROM facts
  WHERE kb_id = #{kbId} AND subject_id = #{subjectId}
    AND predicate_id IS NOT DISTINCT FROM #{predicateId}
    AND object_id IS NOT DISTINCT FROM #{objectId}
    AND object_value IS NOT DISTINCT FROM #{objectValue,typeHandler=tech.seexun.jknow.store.typehandler.JsonNodeTypeHandler}
    AND invalidated_at IS NULL
  LIMIT 1

SELECT 1 FROM pending_facts
  WHERE kb_id = #{kbId} AND subject_id = #{subjectId}
    AND predicate_id IS NOT DISTINCT FROM #{predicateId}
    AND object_id IS NOT DISTINCT FROM #{objectId}
    AND object_value IS NOT DISTINCT FROM #{objectValue,typeHandler=tech.seexun.jknow.store.typehandler.JsonNodeTypeHandler}
    AND phrase IS NOT DISTINCT FROM #{phrase}
  LIMIT 1

SELECT 1 FROM rejected_facts
  WHERE kb_id = #{kbId} AND subject_id = #{subjectId}
    AND predicate_id IS NOT DISTINCT FROM #{predicateId}
    AND object_id = #{objectId}
    AND phrase IS NOT DISTINCT FROM #{phrase}
  LIMIT 1
